local addon_name, addon = ...

local L = LibStub("AceLocale-3.0"):NewLocale(addon_name, "deDE", false, true)
if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- 8177cc43 English: Caster Balance from level 1 to 70, and the default for any Druid no other
--     premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving,
--     Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and
--     you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire
--     (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the
--     Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight,
--     Innervate when low.
[1] = "Gleichgewicht als Zauberwirker von Stufe 1 bis 70 und der Standard für jeden Druiden, zu dem keine andere integrierte Rotation passt. Zieht mit Sternenfeuer (Zorn vor Stufe 20), Insektenschwarm und Mondfeuer in Bewegung, Feenfeuer in einer Gruppe, Hurrikan für drei oder mehr Gegner, Mondfeuer, wenn es ausgelaufen ist und Sie 30 % Mana haben, Sternenfeuer bei Anmut der Natur, Zorn gegen ein Ziel im Nahkampf, dann Sternenfeuer (Zorn, bevor es erlernt ist). Keine Empfehlungen in Katzen-, Bären- oder Reisegestalt. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Omen der Klarsicht, Mondkingestalt, Naturgewalt bei einem langen Kampf, Anregen bei wenig Mana.",
-- 9f5ae657 English: Feral (Icy Veins, Warcraft Tavern & simulator)
[2] = "Wilder Kampf (Icy Veins, Warcraft Tavern & Simulation)",
-- 43a0ca32 English: Cat and bear for the Feral tree, following your form. Cat: stealth opener
--     (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that
--     lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or
--     Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops,
--     Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates,
--     Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul
--     with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an
--     optional step that starts off (it needs a powershift macro).
[3] = "Katze und Bär für den Baum Wilder Kampf, je nach Ihrer Gestalt. Katze: Eröffner aus der Verstohlenheit (Anspringen, Verheeren oder Schreddern), Feenfeuer (Tiergestalt), Zerfetzen bei vier Combopunkten auf ein Ziel, das lange genug lebt, Wilder Biss zwischen Zerfetzen ohne Freizaubern, Zerfleischen aufrechterhalten, Schreddern von hinten oder Zerfleischen/Klaue, wenn das Ziel Sie angreift. Bär: Feenfeuer, Aufschlitzen erneuert, bevor es ausläuft, Demoralisierendes Gebrüll, außer ein Ruf eines Kriegers ist aktiv, Prankenhieb gegen Gruppen, Zerfleischen, fünfmal Aufschlitzen, Prankenhieb. In Zauberergestalt schlägt sie Katzen- (oder Bären-)gestalt vor. Erinnerungen: Mal, Dornen, Omen, Zermalmen bei überschüssiger Wut, Tigerfuror vor einem Pull, Rasende Regeneration. Powershifting ist ein optionaler Schritt, der deaktiviert beginnt (er benötigt ein Powershift-Makro).",
-- 4c55a525 English: Feral (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid, The
--     Burning Crusade Classic (variant key: Feral / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[4] = "Wilder Kampf (Wowhead)",
-- 9092413a English: Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off
--     by default: enable it and disable that one, or raise its priority. Rip whenever it is down at
--     four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears
--     spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana.
--     Otherwise the same as the Icy Veins variant.
[5] = "Wilder Kampf nach Wowhead, eine Alternative zur empfohlenen integrierten Rotation für Wilden Kampf nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zerfetzen, sobald es fehlt, bei vier Combopunkten und Wilder Biss nur auf ein Ziel kurz vor dem Tod (kein Bite-Weaving); Bären nutzen freie globale Abklingzeiten für Aufschlitzen vor Prankenhieb. Anregen, wenn einer Katze das Mana ausgeht. Ansonsten wie die Icy-Veins-Variante.",
-- da5557c1 English: Healing for the Restoration tree on your friendly target (or yourself): Healing
--     Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or
--     Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then
--     Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and
--     Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility,
--     Innervate and Rebirth. Choosing whom to heal and downranking stay with you.
[6] = "Heilung für den Baum Wiederherstellung auf Ihr freundliches Ziel (oder Sie selbst): Heilende Berührung nach Schnelligkeit der Natur, Rasche Heilung auf ein sterbendes Ziel mit Ihrer Verjüngung oder Ihrem Nachwachsen, drei rollierende Blühendes Leben im Kampf, Verjüngung und Nachwachsen, wenn sie fehlen, dann Nachwachsen im Baum des Lebens oder Heilende Berührung außerhalb davon. Ein feindliches Ziel erhält für das Solospiel Mondfeuer und Zorn. Erinnerungen: Mal, Omen, Baum des Lebens, Schnelligkeit der Natur, Gelassenheit, Anregen und Wiedergeburt. Wen Sie heilen und das Herabstufen von Rängen bleiben Ihnen überlassen.",
-- fdac9d3d English: Balance from level 1 to 60, and the default for any Forever Druid no other
--     premade fits (levels 1–9, untalented casters, solo Restoration). Pulls with Wrath; while
--     moving, refreshes Moonfire, Insect Swarm and, in a group, Faerie Fire. Hurricane when three
--     or more enemies are fighting you, then your own Moonfire and Insect Swarm, Starfire while
--     Eclipse charges or Clearcasting are up, and Wrath; when you cannot afford Wrath it lets you
--     melee. Health and mana are hidden from addons on Forever, so healing yourself and judging
--     whether a target is worth a DoT are your call. Reminders: Mark of the Wild, Thorns while
--     solo, Moonkin Form, a pre-pull Rejuvenation while solo, Nature's Grasp when a mob is on you,
--     Innervate whenever it is ready in combat while solo. Form changes, crowd control, Barkskin
--     and target choice stay with you. Built from level-30 beta guides; level 31–60 steps follow
--     the class design and are untested.
[7] = "Gleichgewicht von Stufe 1 bis 60 und der Standard für jeden Forever-Druiden, zu dem keine andere integrierte Rotation passt (Stufen 1–9, Zauberwirker ohne Talente, Wiederherstellung beim Solospiel). Zieht mit Zorn; in Bewegung erneuert sie Mondfeuer, Insektenschwarm und in einer Gruppe Feenfeuer. Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, dann Ihr eigenes Mondfeuer und Ihren Insektenschwarm, Sternenfeuer, solange Ladungen von Finsternis oder Freizaubern aktiv sind, und Zorn; wenn Sie sich Zorn nicht leisten können, lässt sie Sie im Nahkampf kämpfen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wie Sie sich heilen und ob sich ein DoT auf einem Ziel lohnt. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Moonkingestalt, eine Verjüngung vor dem Pull beim Solospiel, Griff der Natur, wenn ein Gegner Sie angreift, Anregen, sobald es beim Solospiel im Kampf bereit ist. Gestaltwechsel, Kontrolleffekte, Baumrinde und Zielwahl bleiben Ihnen überlassen. Erstellt aus Beta-Leitfäden für Stufe 30; die Schritte für Stufe 31–60 folgen dem Klassendesign und sind ungetestet.",
-- 78805a61 English: Balance, Multi-DoT (Warcraft Tavern)
[8] = "Gleichgewicht, Multi-DoT (Warcraft Tavern)",
-- 3841b7e5 English: Warcraft Tavern's Multi-DoT leveling style, an alternative to the recommended
--     Balance premade, off by default: enable it and disable that one, or raise its priority. Pulls
--     with Wrath, keeps your Moonfire and Insect Swarm on the target, roots it with Entangling
--     Roots once both are running while another enemy is fighting you, then Wrath. No Starfire (the
--     build skips Eclipse). Switching to the next enemy is up to you. Reminders: Mark of the Wild,
--     Thorns while solo.
[9] = "Multi-DoT-Levelstil von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zieht mit Zorn, hält Ihr Mondfeuer und Ihren Insektenschwarm auf dem Ziel, wurzelt es mit Wucherwurzeln fest, sobald beide wirken und ein weiterer Gegner gegen Sie kämpft, dann Zorn. Kein Sternenfeuer (der Build verzichtet auf Finsternis). Der Wechsel zum nächsten Gegner bleibt Ihnen überlassen. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel.",
-- 78daf4ac English: Feral, Cat and Bear
[10] = "Wilder Kampf, Katze und Bär",
-- 420ae9f2 English: Cat and Bear in one premade, chosen by your form; it takes over once Feral is
--     your main talent tree (or has 11 points), or when you shift into Cat or Bear Form. Cat:
--     Ravage or Shred from Prowl, Faerie Fire, Rip at four combo points, Ferocious Bite once Rip
--     runs, Rake, then Shred when the target is not facing you (Claw otherwise). Bear: Faerie Fire
--     and Feral Charge at range, Demoralizing Roar in a group or on two enemies, Primal Bite, Swipe
--     on three or more, Lacerate, Swipe. In caster form it suggests Cat Form (Bear before you have
--     Cat). Reminders: Maul whenever you can afford it in Bear Form, Enrage, Berserk on big pulls
--     or elites, Innervate while solo, Mark of the Wild, Thorns. Health, energy, rage and mana are
--     hidden from addons on Forever, so powershifting, Frenzied Regeneration and healing yourself
--     are your call. Taunts, interrupts and positioning stay with you.
[11] = "Katze und Bär in einer integrierten Rotation, gewählt nach Ihrer Gestalt; sie übernimmt, sobald Wilder Kampf Ihr Haupttalentbaum ist (oder 11 Punkte hat) oder Sie in Katzen- oder Bärengestalt wechseln. Katze: Verheeren oder Schreddern aus Schleichen, Feenfeuer, Zerfetzen bei vier Combopunkten, Wilder Biss, sobald Zerfetzen wirkt, Krallenhieb, dann Schreddern, wenn das Ziel Ihnen nicht zugewandt ist (sonst Klaue). Bär: Feenfeuer und Wilde Attacke auf Distanz, Demoralisierendes Gebrüll in einer Gruppe oder gegen zwei Gegner, Urtümlicher Biss, Prankenhieb gegen drei oder mehr, Aufschlitzen, Prankenhieb. In Zauberergestalt schlägt sie Katzengestalt vor (Bärengestalt, bevor Sie Katzengestalt haben). Erinnerungen: Zermalmen in Bärengestalt, wann immer Sie es sich leisten können, Wutanfall, Berserker bei großen Pulls oder gegen Elitegegner, Anregen beim Solospiel, Mal der Wildnis, Dornen. Gesundheit, Energie, Wut und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Powershifting, Rasende Regeneration und Selbstheilung. Spotten, Unterbrechungen und Positionierung bleiben Ihnen überlassen.",
-- 2bcf6375 English: Group healing after Warcraft Tavern, once Restoration is your main talent tree
--     with 11 points. Heals your current friendly target: Swiftmend on a target with your HoT, Wild
--     Growth, Regrowth and Rejuvenation when missing, Healing Touch. Health and mana are hidden
--     from addons on Forever, so the target you pick is the only sign of who needs healing. On a
--     hostile target: Moonfire, Insect Swarm, Wrath. Reminders: Innervate in combat, Nature's
--     Swiftness on a friendly target in combat, Remove Curse and Abolish Poison, Mark of the Wild;
--     Tranquility is yours. You pick who to heal and the spell rank; solo Restoration uses the
--     Balance premade.
[12] = "Gruppenheilung nach Warcraft Tavern, sobald Wiederherstellung Ihr Haupttalentbaum mit 11 Punkten ist. Heilt Ihr aktuelles freundliches Ziel: Rasche Heilung auf ein Ziel mit Ihrem HoT, Wildwuchs, Nachwachsen und Verjüngung, wenn sie fehlen, Heilende Berührung. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht. Gegen ein feindliches Ziel: Mondfeuer, Insektenschwarm, Zorn. Erinnerungen: Anregen im Kampf, Schnelligkeit der Natur auf ein freundliches Ziel im Kampf, Fluch aufheben und Vergiftung aufheben, Mal der Wildnis; Gelassenheit bleibt Ihnen überlassen. Wen Sie heilen und den Zauberrang wählen Sie; Wiederherstellung beim Solospiel nutzt die integrierte Gleichgewichtsrotation.",
-- e898fb57 English: Restoration, HoTs first (Icy Veins)
[13] = "Wiederherstellung, HoTs zuerst (Icy Veins)",
-- 62addd5b English: Icy Veins' HoT-first healing, an alternative to the recommended Restoration
--     premade, off by default: enable it and disable that one, or raise its priority. On your
--     friendly target: Rejuvenation, then Regrowth when missing, Healing Touch only with both HoTs
--     running, Swiftmend on a HoT target, then Wild Growth (health is hidden on Forever, so the
--     target you pick decides who is healed). Innervate on cooldown. Otherwise the same reminders
--     and hostile-target list as the Restoration premade.
[14] = "HoT-zuerst-Heilung nach Icy Veins, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Ihrem freundlichen Ziel: Verjüngung, dann Nachwachsen, wenn es fehlt, Heilende Berührung nur, wenn beide HoTs wirken, Rasche Heilung auf ein Ziel mit HoT, dann Wildwuchs (Gesundheit ist unter Forever verborgen, daher entscheidet das Ziel, das Sie wählen, wer geheilt wird). Anregen bei Abklingzeit-Ende. Ansonsten dieselben Erinnerungen und dieselbe Liste für feindliche Ziele wie die integrierte Wiederherstellungsrotation.",
-- 3941b2ad English: Recommended for Balance. Highlights the spell Blizzard's Assisted Combat
--     suggests next, the one rotation advice the game still lets an addon read in Midnight combat;
--     it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves
--     to you: Celestial Alignment (or Incarnation) in combat, Solar Beam on an interruptible cast,
--     Moonkin Form and Mark of the Wild between pulls, and Barkskin and your racial cooldown
--     whenever they are ready in combat. Enemy casts are hidden in combat, so Solar Beam lights
--     only where the game shows them; health is hidden on Retail, so when to use Barkskin is your
--     call.
[15] = "Empfohlen für Gleichgewicht. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Himmlische Ausrichtung (oder Inkarnation) im Kampf, Sonnenstrahl bei einem unterbrechbaren Zauber, Mondkingestalt und Mal der Wildnis zwischen den Kämpfen sowie Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Sonnenstrahl nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Baumrinde Ihnen überlassen.",
-- 9253fca4 English: Reference only, off by default: the guides' Balance priority. Your DoTs,
--     Eclipse and procs are hidden from addons in Midnight combat, so it cannot run there; read it,
--     or clone it to experiment. Astral Power is hidden on Retail, so Starsurge spends at its cost
--     instead of before the cap. Pulls with Moonkin Form and Wrath. Sunfire and Moonfire when
--     missing or about to fall off; Eclipse when neither is active (Lunar on three or more enemies,
--     Solar otherwise); Starfall on Starweaver's Warp, Touch the Cosmos or packs; Starsurge on
--     Starweaver's Weft or Touch the Cosmos; New, Half and Full Moon; Wild Mushroom in an Eclipse;
--     Starsurge whenever you can afford it; Starfire in a Lunar Eclipse or on packs, else Wrath.
--     Reminders: Celestial Alignment or Incarnation, Fury of Elune and Force of Nature before an
--     Eclipse, Convoke in Celestial Alignment, Solar Beam, plus the utility reminders.
[16] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Gleichgewicht. Ihre DoTs, Finsternis und Procs sind im Kampf in Midnight für Addons verborgen, daher kann sie dort nicht laufen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Astrale Macht ist unter Retail verborgen, daher wirkt Sternensog zu seinen Kosten statt vor dem Maximum. Zieht mit Mondkingestalt und Zorn. Sonnenfeuer und Mondfeuer, wenn sie fehlen oder bald auslaufen; Finsternis, wenn keine aktiv ist (Mondfinsternis gegen drei oder mehr Gegner, sonst Sonnenfinsternis); Sternenregen bei Schuss des Sternwebers, Den Kosmos berühren oder gegen Gruppen; Sternensog bei Kette des Sternwebers oder Den Kosmos berühren; Neumond, Halbmond und Vollmond; Wildpilz während einer Finsternis; Sternensog, wann immer Sie es sich leisten können; Sternenfeuer während einer Mondfinsternis oder gegen Gruppen, sonst Zorn. Erinnerungen: Himmlische Ausrichtung oder Inkarnation, Zorn der Elune und Naturgewalt vor einer Finsternis, Konvokation während Himmlischer Ausrichtung, Sonnenstrahl, dazu die Erinnerungen an Hilfsfähigkeiten.",
-- e3e320b6 English: Recommended for Feral. Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you:
--     Berserk (or Incarnation) in combat, Skull Bash on an interruptible cast, Survival Instincts,
--     Barkskin and your racial cooldown whenever they are ready in combat, and Cat Form and Mark of
--     the Wild between pulls. Enemy casts are hidden in combat, so the interrupt lights only where
--     the game shows them; health is hidden on Retail, so when to use the defensives is your call.
[17] = "Empfohlen für Wildheit. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Berserker (oder Inkarnation) im Kampf, Schädelstoß bei einem unterbrechbaren Zauber, Überlebensinstinkte, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, sowie Katzengestalt und Mal der Wildnis zwischen den Kämpfen. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz der Defensivfähigkeiten Ihnen überlassen.",
-- 2be7f2bb English: Reference only, off by default: the guides' Feral priority. Bleeds and procs
--     are hidden in Midnight combat (combo points are not), so it cannot run there; energy is
--     hidden on Retail. Opens with Cat Form, Prowl and Rake. Chomp; Ferocious Bite on Apex
--     Predator's Craving; at five combo points Primal Wrath on two or more enemies, Rip when
--     missing or in its last seconds, else Ferocious Bite, waiting for energy rather than building
--     past five; below five, Rake when missing or about to fall off, Lunar Inspiration Moonfire,
--     Swipe on three or more enemies, Shred. Reminders: Tiger's Fury whenever it is ready in
--     combat, Berserk or Incarnation and Feral or Frantic Frenzy (at two points or fewer) in
--     Tiger's Fury, Convoke in Tiger's Fury and Berserk with Rip up, Skull Bash, Survival
--     Instincts, plus the utility reminders. Snapshotting is left to you.
[18] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Wildheit. Blutungen und Procs sind im Kampf in Midnight verborgen (Combopunkte nicht), daher kann sie dort nicht laufen; Energie ist unter Retail verborgen. Eröffnet mit Katzengestalt, Schleichen und Krallenhieb. Zubeißen; Wilder Biss bei Gelüst des Eliteraubtiers; bei fünf Combopunkten Urzorn gegen zwei oder mehr Gegner, Zerfetzen, wenn es fehlt oder in seinen letzten Sekunden ist, sonst Wilder Biss, wobei auf Energie gewartet statt über fünf Punkte hinaus aufgebaut wird; unter fünf Krallenhieb, wenn er fehlt oder bald ausläuft, Mondfeuer mit Mondinspiration, Prankenhieb gegen drei oder mehr Gegner, Schreddern. Erinnerungen: Tigerfuror, wann immer er im Kampf bereit ist, Berserker oder Inkarnation sowie Wilde Raserei oder Tobende Raserei (bei zwei Punkten oder weniger) während Tigerfuror, Konvokation während Tigerfuror und Berserker bei aktivem Zerfetzen, Schädelstoß, Überlebensinstinkte, dazu die Erinnerungen an Hilfsfähigkeiten. Snapshotting bleibt Ihnen überlassen.",
-- 2a16fe9b English: Recommended for Guardian. Highlights the spell Blizzard's Assisted Combat
--     suggests next, the one rotation advice the game still lets an addon read in Midnight combat;
--     Assisted Combat plays for damage only. Alongside it, reminders for what it leaves to you:
--     Berserk (or Incarnation) and Convoke the Spirits in combat, Ironfur, Frenzied Regeneration,
--     Survival Instincts, Barkskin and your racial cooldown whenever they are ready in combat,
--     Skull Bash on an interruptible cast, and Bear Form and Mark of the Wild between pulls. Enemy
--     casts are hidden in combat, so Skull Bash lights only where the game shows them; health and
--     rage are hidden on Retail, so when to use the defensives is your call and Ironfur cannot wait
--     for a rage threshold.
[19] = "Empfohlen für Wächter. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; der Kampfassistent spielt nur auf Schaden. Daneben Erinnerungen an das, was er Ihnen überlässt: Berserker (oder Inkarnation) und Konvokation der Geister im Kampf, Eisenfell, Rasende Regeneration, Überlebensinstinkte, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, Schädelstoß bei einem unterbrechbaren Zauber sowie Bärengestalt und Mal der Wildnis zwischen den Kämpfen. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Schädelstoß nur dort auf, wo das Spiel sie anzeigt; Gesundheit und Wut sind unter Retail verborgen, daher bleibt der Einsatz der Defensivfähigkeiten Ihnen überlassen, und Eisenfell kann nicht auf eine Wutschwelle warten.",
-- 32ed36e2 English: Reference only, off by default: the guides' Guardian priority. Debuffs and
--     procs are hidden in Midnight combat, so it cannot run there; rage and health are hidden on
--     Retail, so the 80-rage Raze and Maul dump is left to you. Thrash and Mangle on cooldown, Red
--     Moon on a single target, Moonfire when missing or on Galactic Guardian, Swipe. Reminders
--     whenever they are ready in combat: Ironfur, Frenzied Regeneration, Survival Instincts; Bear
--     Form between pulls; Berserk or Incarnation, Lunar Beam, Convoke, Heart of the Wild, Skull
--     Bash, plus the utility reminders.
[20] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Wächter. Schwächungszauber und Procs sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Wut und Gesundheit sind unter Retail verborgen, daher bleibt das Abladen von Wut mit Plätten und Zermalmen ab 80 Wut Ihnen überlassen. Hauen und Zerfleischen bei Abklingzeit-Ende, Blutmond gegen ein einzelnes Ziel, Mondfeuer, wenn es fehlt, oder bei Galaktischem Wächter, Prankenhieb. Erinnerungen, wann immer sie im Kampf bereit sind: Eisenfell, Rasende Regeneration, Überlebensinstinkte; Bärengestalt zwischen den Kämpfen; Berserker oder Inkarnation, Mondstrahl, Konvokation, Herz der Wildnis, Schädelstoß, dazu die Erinnerungen an Hilfsfähigkeiten.",
-- beb78fe5 English: Defensive reference (SimulationCraft)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Retail (current expansion) (variant key: GuardianSimc). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[21] = "Defensive Referenz (SimulationCraft)",
-- f0f6bfc8 English: Reference only, off by default: SimulationCraft's Guardian list, which spends
--     rage on Ironfur first. Hidden combat data keeps it from running in Midnight combat, and rage
--     is hidden on Retail, so its rage thresholds are left out. Ironfur in Berserk; Thrash when
--     missing, about to fall off or under three stacks; Maul on Gory Fur; Thrash on three or more
--     enemies; Mangle while Red Moon ticks; Red Moon; Mangle; Thrash; Moonfire; Swipe. Its cat-form
--     weaving is left out. Reminders: Bear Form, Frenzied Regeneration, Survival Instincts, Berserk
--     or Incarnation, Lunar Beam, Convoke, Skull Bash, plus the utility reminders.
[22] = "Nur als Referenz, standardmäßig deaktiviert: die Liste von SimulationCraft für Wächter, die Wut zuerst für Eisenfell ausgibt. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft, und Wut ist unter Retail verborgen, daher entfallen ihre Wutschwellen. Eisenfell während Berserker; Hauen, wenn es fehlt, bald ausläuft oder unter drei Stapeln liegt; Zermalmen bei Blutigem Fell; Hauen gegen drei oder mehr Gegner; Zerfleischen, solange Blutmond tickt; Blutmond; Zerfleischen; Hauen; Mondfeuer; Prankenhieb. Das Einweben von Katzengestalt lässt sie aus. Erinnerungen: Bärengestalt, Rasende Regeneration, Überlebensinstinkte, Berserker oder Inkarnation, Mondstrahl, Konvokation, Schädelstoß, dazu die Erinnerungen an Hilfsfähigkeiten.",
-- f2046f35 English: Blizzard Assisted with maintenance
[23] = "Blizzard-Kampfassistent mit Pflege",
-- fc05cf7d English: Recommended for Restoration. With an enemy targeted it highlights Blizzard's
--     Assisted Combat suggestion, Blizzard's Restoration damage list in cat or caster form.
--     Otherwise it suggests Icy Veins' maintenance casts on your friendly target (or yourself):
--     Lifebloom, Efflorescence in combat, Swiftmend on a Rejuvenation, Wild Growth in a group in
--     combat, Regrowth on Clearcasting or five Abundance stacks, Rejuvenation when missing. Health
--     and mana are hidden on Retail, so these follow the target you choose, not how hurt anyone is;
--     your heals over time are hidden in Midnight combat, so the steps that read them wait there.
--     Whom to heal, and every healing cooldown, is yours. Reminders: Innervate, Barkskin and your
--     racial cooldown whenever they are ready in combat, Mark of the Wild between pulls.
[24] = "Empfohlen für Wiederherstellung. Mit einem anvisierten Gegner hebt sie den Vorschlag von Blizzards Kampfassistent hervor, Blizzards Schadensliste für Wiederherstellung in Katzen- oder Normalgestalt. Andernfalls schlägt sie die Erhaltungszauber nach Icy Veins auf Ihr freundliches Ziel (oder Sie selbst) vor: Blühendes Leben, Erblühen im Kampf, Rasche Heilung auf eine Verjüngung, Wildwuchs in einer Gruppe im Kampf, Nachwachsen bei Freizaubern oder fünf Stapeln Überfluss, Verjüngung, wenn sie fehlt. Gesundheit und Mana sind unter Retail verborgen, daher folgen diese dem Ziel, das Sie wählen, und nicht danach, wie verletzt jemand ist; Ihre Heilungen über Zeit sind im Kampf in Midnight verborgen, daher warten die Schritte, die sie lesen, dort. Wen Sie heilen, und jede Heil-Abklingzeit liegen bei Ihnen. Erinnerungen: Anregen, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, Mal der Wildnis zwischen den Kämpfen.",
-- 65160bfe English: Recommended before you choose a specialization (while the game reports the
--     Druid's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Druid premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[25] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Druiden meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Druiden-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- df418098 English: Balance from level 1 to 60, and the Druid default before talents or when no
--     other premade fits. Starfire as the filler once learned (Wrath before that, Starfire first on
--     a Nature's Grace proc), Moonfire and Insect Swarm kept on targets that will live while your
--     mana is above 30%, Hurricane when three or more enemies are on you, Faerie Fire in a group,
--     instants while moving, melee when out of mana. In Cat or Bear Form it gives the Feral advice
--     instead. Reminders: Mark of the Wild, Thorns when solo, Omen of Clarity, Moonkin Form when
--     you are in no form, Innervate, Nature's Grasp. Downranking Starfire, roots and target choice
--     stay with you.
[26] = "Gleichgewicht von Stufe 1 bis 60 und der Druiden-Standard vor den Talenten oder wenn keine andere integrierte Rotation passt. Sternenfeuer als Füller, sobald erlernt (davor Zorn; Sternenfeuer zuerst bei einem Proc von Anmut der Natur), Mondfeuer und Insektenschwarm auf Zielen, die lange genug leben, aufrechterhalten, solange Ihr Mana über 30 % liegt, Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, Feenfeuer in einer Gruppe, Spontanzauber in Bewegung, Nahkampf ohne Mana. In Katzen- oder Bärengestalt gibt sie stattdessen die Empfehlungen für Wilder Kampf. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Omen der Klarsicht, Moonkingestalt, wenn Sie in keiner Gestalt sind, Anregen, Griff der Natur. Herabstufen von Sternenfeuer, Wucherwurzeln und Zielwahl bleiben Ihnen überlassen.",
-- 3c5a26cc English: Balance (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Classic Era (variant key: Balance / IcyVeins). Names in parentheses (guide or tool such as
--     Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are
--     proper names and stay unchanged.
[27] = "Gleichgewicht (Icy Veins)",
-- 72e2ae3e English: Icy Veins' raid list for realms with the 16-debuff limit, an alternative to the
--     recommended Balance premade, off by default: enable it and disable that one, or raise its
--     priority. Starfire and nothing else, no Moonfire or Insect Swarm, Hurricane when three or
--     more enemies are on you, Wrath only before Starfire is learned. Same reminders as the
--     recommended premade.
[28] = "Die Schlachtzugsliste von Icy Veins für Realms mit dem Limit von 16 Schwächungszaubern, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Nur Sternenfeuer, kein Mondfeuer und kein Insektenschwarm, Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, Zorn nur, bevor Sternenfeuer erlernt ist. Dieselben Erinnerungen wie die empfohlene integrierte Gleichgewicht-Rotation.",
-- 46898c22 English: Feral cat and bear from level 10 when Feral is your main talent tree; your form
--     decides which. Cat: stealth opener, Faerie Fire (Feral) kept up, Clearcasting spent on Shred,
--     a finisher from four combo points (Rip before Ferocious Bite is learned and on long fights
--     outside raids, Bite under 63 energy), Rake outside raids, Shred from behind or Claw when the
--     target is on you, and a powershift (Cat Form again) when far short of energy with Furor 5/5
--     and mana to spare. Bear: Enrage when starved, Demoralizing Roar on packs and elites unless a
--     warrior's Shout is up, Swipe on two or more and with spare rage, Faerie Fire (Feral)
--     otherwise. Caster form: shift. Reminders: Maul every swing, Tiger's Fury before a pull,
--     Manual Crowd Pummeler, Innervate, Frenzied Regeneration. Positioning stays with you.
[29] = "Wilder Kampf als Katze und Bär ab Stufe 10, wenn Wilder Kampf Ihr Haupttalentbaum ist; Ihre Gestalt entscheidet, welche Variante. Katze: Eröffner aus der Verstohlenheit, Feenfeuer (Tiergestalt) aufrechterhalten, Freizaubern für Schreddern genutzt, ein Finisher ab vier Combopunkten (Zerfetzen, bevor Wilder Biss erlernt ist, und bei langen Kämpfen außerhalb von Schlachtzügen, Wilder Biss unter 63 Energie), Krallenhieb außerhalb von Schlachtzügen, Schreddern von hinten oder Klaue, wenn das Ziel Sie angreift, und ein Powershift (erneut Katzengestalt), wenn Ihnen viel Energie fehlt, mit Ingrimm 5/5 und überschüssigem Mana. Bär: Wutanfall bei Wutmangel, Demoralisierendes Gebrüll gegen Gruppen und Elitegegner, außer der Ruf eines Kriegers ist aktiv, Prankenhieb gegen zwei oder mehr Gegner und bei überschüssiger Wut, sonst Feenfeuer (Tiergestalt). In Zauberergestalt: Gestaltwechsel. Erinnerungen: Zermalmen bei jedem Schlag, Tigerfuror vor einem Pull, Manueller Meuteverprügler, Anregen, Rasende Regeneration. Positionierung bleibt Ihnen überlassen.",
-- db52e95b English: Feral (Warcraft Tavern, Rip and Bite)
[30] = "Wilder Kampf (Warcraft Tavern, Zerfetzen und Wilder Biss)",
-- eb72eaac English: Warcraft Tavern's powershifting list, an alternative to the recommended Feral
--     premade, off by default: enable it and disable that one, or raise its priority. Rip at five
--     combo points whenever it is missing, raids included, then Ferocious Bite from four combo
--     points under 63 energy, Shred from behind, powershift when far short of energy. Bear and
--     reminders as the recommended premade.
[31] = "Die Powershifting-Liste von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zerfetzen bei fünf Combopunkten, wann immer es fehlt, auch in Schlachtzügen, dann Wilder Biss ab vier Combopunkten unter 63 Energie, Schreddern von hinten, Powershift, wenn Ihnen viel Energie fehlt. Bär und Erinnerungen wie bei der empfohlenen integrierten Rotation für Wilder Kampf.",
-- a2889e4e English: Feral (Warcraft Tavern, no powershifting)
[32] = "Wilder Kampf (Warcraft Tavern, ohne Powershifting)",
-- 1f3cd5d3 English: Warcraft Tavern's list without powershifting, an alternative to the recommended
--     Feral premade, off by default: enable it and disable that one, or raise its priority. Build
--     to five combo points with Shred (Claw from the front), then Rip on a target that will live,
--     Tiger's Fury, Ferocious Bite; otherwise wait for energy. Bear and reminders as the
--     recommended premade.
[33] = "Die Liste von Warcraft Tavern ohne Powershifting, eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Mit Schreddern (Klaue von vorn) bis fünf Combopunkte aufbauen, dann Zerfetzen auf ein Ziel, das lange genug lebt, Tigerfuror, Wilder Biss; sonst auf Energie warten. Bär und Erinnerungen wie bei der empfohlenen integrierten Rotation für Wilder Kampf.",
-- a1394efb English: Feral (Wowhead raid bear)
[34] = "Wilder Kampf (Wowhead, Schlachtzugsbär)",
-- ee7a8843 English: The cat of the recommended Feral premade with Wowhead's geared raid bear: Maul
--     every swing (tab-Maul packs yourself), Swipe only with 60 rage to spare, Faerie Fire (Feral)
--     otherwise, no Demoralizing Roar and no Enrage in combat. An alternative to the recommended
--     Feral premade, off by default: enable it and disable that one, or raise its priority.
[35] = "Die Katze der empfohlenen integrierten Rotation für Wilder Kampf mit dem gut ausgerüsteten Schlachtzugsbären von Wowhead: Zermalmen bei jedem Schlag (Zermalmen per Tab-Wechsel auf Gruppen übernehmen Sie selbst), Prankenhieb nur mit 60 überschüssiger Wut, sonst Feenfeuer (Tiergestalt), kein Demoralisierendes Gebrüll und kein Wutanfall im Kampf. Eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 877af0fd English: Restoration from level 10 when Restoration is your main talent tree. Heals your
--     current friendly target: Healing Touch after Nature's Swiftness, Swiftmend below 40% on your
--     own HoT, Rejuvenation and Regrowth kept rolling, Regrowth as the main heal with Improved
--     Regrowth, full Healing Touch below 45% or on a Nature's Grace proc, rank 4 Healing Touch
--     otherwise. On an enemy: Moonfire, Insect Swarm and Wrath. Silent in Cat or Bear Form.
--     Reminders: Mark of the Wild, Omen of Clarity, Nature's Swiftness, Tranquility, Innervate,
--     Rebirth, poison and curse removal. Choosing whom to heal stays with you.
[36] = "Wiederherstellung ab Stufe 10, wenn Wiederherstellung Ihr Haupttalentbaum ist. Heilt Ihr aktuelles freundliches Ziel: Heilende Berührung nach Schnelligkeit der Natur, Rasche Heilung unter 40 % auf Ihrem eigenen HoT, Verjüngung und Nachwachsen fortlaufend aufrechterhalten, Nachwachsen als Hauptheilung mit Verbessertem Nachwachsen, Heilende Berührung im höchsten Rang unter 45 % oder bei einem Proc von Anmut der Natur, sonst Heilende Berührung Rang 4. Gegen einen Gegner: Mondfeuer, Insektenschwarm und Zorn. Still in Katzen- oder Bärengestalt. Erinnerungen: Mal der Wildnis, Omen der Klarsicht, Schnelligkeit der Natur, Gelassenheit, Anregen, Wiedergeburt, Entfernen von Giften und Flüchen. Wen Sie heilen, bleibt Ihnen überlassen.",
-- b765b6c7 English: Restoration (Warcraft Tavern)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Classic Era (variant key: Restoration / WarcraftTavern). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[37] = "Wiederherstellung (Warcraft Tavern)",
-- 8cdc97b9 English: Warcraft Tavern's damage tiers, an alternative to the recommended Restoration
--     premade, off by default: enable it and disable that one, or raise its priority. On your
--     friendly target, with no HoT upkeep while damage is low: Swiftmend below 40%, rank 5 Regrowth
--     below 50%, Rejuvenation and rank 3 Regrowth below 75%, full Healing Touch on a Nature's Grace
--     proc, rank 3 Healing Touch below 90%. Reminders as the recommended premade.
[38] = "Die Schadensstufen von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Ihrem freundlichen Ziel, ohne HoT-Pflege bei geringem Schaden: Rasche Heilung unter 40 %, Nachwachsen Rang 5 unter 50 %, Verjüngung und Nachwachsen Rang 3 unter 75 %, Heilende Berührung im höchsten Rang bei einem Proc von Anmut der Natur, Heilende Berührung Rang 3 unter 90 %. Erinnerungen wie bei der empfohlenen integrierten Wiederherstellungsrotation.",
-- d6247adc English: Balance (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Season of Discovery (variant key: Balance). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[39] = "Gleichgewicht (SoD)",
-- 5bcfabec English: Season of Discovery Balance from level 1 to 60, and the default for any Druid
--     no other Season of Discovery premade fits. Starsurge whenever its buff is down, Sunfire and
--     Moonfire on targets that will live, Starfire only when Starsurge or Lunar Eclipse empowers
--     it, Wrath as the filler, Hurricane on six or more enemies (four with Gale Winds engraved),
--     Insect Swarm only while moving. Runes are used as you engrave them. In Cat or Bear Form it
--     gives the Feral advice. Reminders: Moonkin Form, Starfall, instant Healing Touch on a dying
--     friend, curse and poison removal, Wild Growth on a hurt group, Innervate. Spreading DoTs to
--     other targets stays with you.
[40] = "Gleichgewicht in der Saison der Entdeckungen von Stufe 1 bis 60 und der Standard für jeden Druiden, zu dem keine andere integrierte Rotation der Saison der Entdeckungen passt. Sternensog, wann immer sein Stärkungszauber fehlt, Sonnenfeuer und Mondfeuer auf Zielen, die lange genug leben, Sternenfeuer nur, wenn Sternensog oder Mondfinsternis es verstärkt, Zorn als Füller, Hurrikan gegen sechs oder mehr Gegner (vier mit der Rune Orkanwinde), Insektenschwarm nur in Bewegung. Runen werden genutzt, sobald Sie sie gravieren. In Katzen- oder Bärengestalt gibt sie die Empfehlungen für Wilder Kampf. Erinnerungen: Moonkingestalt, Sternenregen, sofortige Heilende Berührung auf einen sterbenden Verbündeten, Entfernen von Flüchen und Giften, Wildwuchs bei einer verletzten Gruppe, Anregen. Das Verteilen von DoTs auf andere Ziele bleibt Ihnen überlassen.",
-- fdb2f205 English: Balance (SoD, Icy Veins)
[41] = "Gleichgewicht (SoD, Icy Veins)",
-- babf9f32 English: Icy Veins' Season of Discovery list, an alternative to the recommended Season
--     of Discovery Balance premade, off by default: enable it and disable that one, or raise its
--     priority. Starsurge on cooldown, Hurricane on four or more enemies (for Gale Winds), Starfire
--     when Starsurge empowers it, Moonfire, Sunfire and Insect Swarm all kept up, Wrath as the
--     filler. Reminders as the recommended premade.
[42] = "Die Liste von Icy Veins für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Sternensog bei Abklingzeit-Ende, Hurrikan gegen vier oder mehr Gegner (für Orkanwinde), Sternenfeuer, wenn Sternensog es verstärkt, Mondfeuer, Sonnenfeuer und Insektenschwarm alle aufrechterhalten, Zorn als Füller. Erinnerungen wie bei der empfohlenen integrierten Rotation.",
-- c4d16f19 English: Balance (SoD, Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Season of Discovery (variant key: Balance / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[43] = "Gleichgewicht (SoD, Wowhead)",
-- 75dabca6 English: Wowhead's Phase 8 list, an alternative to the recommended Season of Discovery
--     Balance premade, off by default: enable it and disable that one, or raise its priority. Wrath
--     to open, Starsurge on cooldown, Hurricane on six or more, Insect Swarm only while moving,
--     Sunfire and Moonfire kept up, Wrath while your Sunfire has under 5 seconds when Elune's Fires
--     is engraved to extend it, Starfire on Lunar Eclipse, Wrath otherwise. Reminders as the
--     recommended premade.
[44] = "Die Liste von Wowhead für Phase 8, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zorn zum Eröffnen, Sternensog bei Abklingzeit-Ende, Hurrikan gegen sechs oder mehr Gegner, Insektenschwarm nur in Bewegung, Sonnenfeuer und Mondfeuer aufrechterhalten, Zorn, solange Ihr Sonnenfeuer weniger als 5 Sekunden hat, wenn Feuer Elunes eingraviert ist, um es zu verlängern, Sternenfeuer bei Mondfinsternis, sonst Zorn. Erinnerungen wie bei der empfohlenen integrierten Rotation.",
-- 3e1ff241 English: Feral cat (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Season of Discovery (variant key: Feral). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[45] = "Wilder Kampf, Katze (SoD)",
-- e7b0a6ca English: Season of Discovery cat, chosen when Savage Roar is engraved (or Feral is your
--     main tree without another legs rune). Faerie Fire (Feral) when none is up, Savage Roar, Swipe
--     (Cat) on four or more enemies, the Mangle debuff, Clearcasting on Shred, Rip at five combo
--     points while Savage Roar has 8 seconds left, Rake, Shred from behind or Mangle from the
--     front, powershift with Furor 5/5, Faerie Fire refresh last. In Bear Form it gives the tank
--     advice. Reminders: Tiger's Fury at 60 energy or less, Berserk with Tiger's Fury, Maul,
--     Innervate. Positioning stays with you.
[46] = "Katze in der Saison der Entdeckungen, gewählt, wenn Wildes Brüllen graviert ist (oder Wilder Kampf ohne eine andere Beinrune Ihr Haupttalentbaum ist). Feenfeuer (Tiergestalt), wenn keines aktiv ist, Wildes Brüllen, Prankenhieb (Katze) gegen vier oder mehr Gegner, der Schwächungszauber von Zerfleischen, Freizaubern für Schreddern, Zerfetzen bei fünf Combopunkten, solange Wildes Brüllen noch 8 Sekunden hat, Krallenhieb, Schreddern von hinten oder Zerfleischen von vorn, Powershift mit Ingrimm 5/5, Erneuern von Feenfeuer zuletzt. In Bärengestalt gibt sie die Tank-Empfehlungen. Erinnerungen: Tigerfuror bei 60 Energie oder weniger, Berserker mit Tigerfuror, Zermalmen, Anregen. Positionierung bleibt Ihnen überlassen.",
-- 3c52079f English: Bear tank (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Season of Discovery (variant key: Tank). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[47] = "Bärentank (SoD)",
-- 6ae09c71 English: Season of Discovery bear tank, chosen when Lacerate is engraved. Faerie Fire
--     (Feral) or Sunfire (Bear) to pull from range, Lacerate before it drops, Mangle on cooldown,
--     Lacerate, Swipe; on three or more enemies Mangle under Berserk and Swipe. In Cat Form it
--     plays the cat list for off-tanking; in caster form it shifts to Bear. Reminders: Maul with 30
--     rage, Berserk, Survival Instincts, Frenzied Regeneration and Barkskin when low, Enrage
--     between pulls, Demoralizing Roar on elites. Taunting and target choice stay with you.
[48] = "Bärentank in der Saison der Entdeckungen, gewählt, wenn Aufschlitzen graviert ist. Feenfeuer (Tiergestalt) oder Sonnenfeuer (Bär), um aus der Distanz zu ziehen, Aufschlitzen, bevor es ausläuft, Zerfleischen bei Abklingzeit-Ende, Aufschlitzen, Prankenhieb; gegen drei oder mehr Gegner Zerfleischen während Berserker und Prankenhieb. In Katzengestalt spielt sie die Katzenliste für das Offtanking; in Zauberergestalt wechselt sie in Bärengestalt. Erinnerungen: Zermalmen bei 30 Wut, Berserker, Überlebensinstinkte, Rasende Regeneration und Baumrinde bei niedriger Gesundheit, Wutanfall zwischen den Pulls, Demoralisierendes Gebrüll gegen Elitegegner. Spotten und Zielwahl bleiben Ihnen überlassen.",
-- 89c7b6e8 English: Bear tank (SoD, simulator cat weave)
[49] = "Bärentank (SoD, Katzen-Weaving nach Simulation)",
-- a83b9a00 English: Off by default; for experts whose gear also grants Savage Roar. The simulator
--     Phase 7 cat weave: leave Bear for Cat when your Rake is down, keep Savage Roar and Rake up
--     (Tiger's Fury, Mangle to build), then return to Dire Bear and play the tank list. Reminders
--     as the recommended tank premade.
[50] = "Standardmäßig deaktiviert; für Experten, deren Ausrüstung zusätzlich Wildes Brüllen gewährt. Das Katzen-Weaving von Simulation für Phase 7: Wechseln Sie vom Bären zur Katze, wenn Ihr Krallenhieb fehlt, halten Sie Wildes Brüllen und Krallenhieb aufrecht (Tigerfuror, Zerfleischen zum Aufbauen), kehren Sie dann zur Terrorbärengestalt zurück und spielen Sie die Tankliste. Erinnerungen wie bei der empfohlenen integrierten Tankrotation.",
-- ba307284 English: Season of Discovery Restoration, chosen when Lifebloom is engraved (or
--     Restoration is your main tree without another legs rune). Heals your current friendly target:
--     instant Healing Touch after Nature's Swiftness or Fury of Stormrage, Wild Growth when two or
--     more nearby are hurt, Swiftmend on your HoT for Efflorescence or below 40%, three Lifebloom
--     stacks refreshed with a second left, Rejuvenation, Regrowth below 60%, Nourish, rank 4
--     Healing Touch. On an enemy: Sunfire, Moonfire, Wrath. Reminders: Tree of Life and Survival
--     Instincts in heavy moments, Nature's Swiftness, Tranquility, Innervate, Rebirth, Revive,
--     dispels. Choosing whom to heal stays with you.
[51] = "Wiederherstellung in der Saison der Entdeckungen, gewählt, wenn Blühendes Leben graviert ist (oder Wiederherstellung ohne eine andere Beinrune Ihr Haupttalentbaum ist). Heilt Ihr aktuelles freundliches Ziel: sofortige Heilende Berührung nach Schnelligkeit der Natur oder Furor von Sturmgrimm, Wildwuchs, wenn zwei oder mehr Verbündete in der Nähe verletzt sind, Rasche Heilung auf Ihrem HoT für Erblühen oder unter 40 %, drei Stapel Blühendes Leben, erneuert, wenn noch eine Sekunde bleibt, Verjüngung, Nachwachsen unter 60 %, Pflege, Heilende Berührung Rang 4. Gegen einen Gegner: Sonnenfeuer, Mondfeuer, Zorn. Erinnerungen: Baum des Lebens und Überlebensinstinkte in schweren Momenten, Schnelligkeit der Natur, Gelassenheit, Anregen, Wiedergeburt, Wiederbelebung, Bannungen. Wen Sie heilen, bleibt Ihnen überlassen.",
-- 3efc9d82 English: For levels 1 to 9, or any druid who has not chosen a specialization yet; the
--     specialization premades take over once you pick one. In Cat Form it keeps Rake up, spends
--     five combo points (or two on a dying target) on Ferocious Bite and builds with Mangle; in
--     Bear Form it uses Mangle and Maul. Otherwise it pulls with Wrath, keeps Moonfire on targets
--     that will last, casts Wrath (Moonfire while moving) and suggests Rejuvenation on yourself
--     when you are below half health and alone. It stops while you cast, travel or have no enemy
--     targeted.
[52] = "Für Stufe 1 bis 9 oder jeden Druiden, der noch keine Spezialisierung gewählt hat; die integrierten Rotationen der Spezialisierungen übernehmen, sobald Sie eine wählen. In Katzengestalt hält sie Krallenhieb aufrecht, gibt fünf Combopunkte (oder zwei auf ein sterbendes Ziel) für Wilden Biss aus und baut mit Zerfleischen auf; in Bärengestalt nutzt sie Zerfleischen und Zermalmen. Sonst zieht sie mit Zorn, hält Mondfeuer auf Zielen, die lange genug leben, wirkt Zorn (Mondfeuer in Bewegung) und schlägt Verjüngung auf Ihnen selbst vor, wenn Sie unter halber Gesundheit und allein sind. Sie pausiert, während Sie wirken, reisen oder keinen Gegner im Ziel haben.",
-- 8e274530 English: Recommended for Balance from level 10, after Wowhead's Phase 5 list and
--     simulator. Keeps Moonfire and Sunfire up and refreshes them inside the matching Eclipse,
--     casts Starfall in Lunar Eclipse, Starsurge on Shooting Stars and on cooldown, Hurricane in
--     Solar or Astral Storm in Lunar at five enemies, Starfire in and after Lunar and Wrath in and
--     after Solar. Rotation Master cannot read Eclipse energy, so between Eclipses it keeps casting
--     Starfire if Starfire was one of your last three casts, otherwise Wrath. Reminders: Mark of
--     the Wild, Moonkin Form, Incarnation as an Eclipse starts and Celestial Alignment as one ends
--     (on elites or long fights), Nature's Vigil, Force of Nature, Nature's Swiftness for Dream of
--     Cenarius, Innervate, Solar Beam, Barkskin and Renewal when low. Wild Mushroom placement stays
--     manual; the Detonate reminder is off by default. It stops while you cast, travel, are in Cat
--     or Bear Form, or have no enemy targeted.
[53] = "Empfohlen für Gleichgewicht ab Stufe 10, nach der Liste von Wowhead für Phase 5 und Simulation. Hält Mondfeuer und Sonnenfeuer aufrecht und erneuert sie in der passenden Finsternis, wirkt Sternenregen in Mondfinsternis, Sternensog bei Sternschnuppen und bei Abklingzeit-Ende, Hurrikan in Sonnenfinsternis oder Astralsturm in Mondfinsternis ab fünf Gegnern, Sternenfeuer in und nach Mondfinsternis und Zorn in und nach Sonnenfinsternis. Rotation Master kann die Finsternisenergie nicht auslesen, daher wirkt sie zwischen den Finsternissen weiter Sternenfeuer, wenn Sternenfeuer einer Ihrer letzten drei Zauber war, sonst Zorn. Erinnerungen: Mal der Wildnis, Mondkingestalt, Inkarnation zu Beginn einer Finsternis und Himmlische Ausrichtung an ihrem Ende (gegen Elitegegner oder bei langen Kämpfen), Wache der Natur, Naturgewalt, Schnelligkeit der Natur für Traum des Cenarius, Anregen, Sonnenstrahl, Baumrinde und Erneuerung bei niedriger Gesundheit. Das Platzieren von Wildpilz bleibt manuell; die Erinnerung an Detonieren ist standardmäßig deaktiviert. Sie pausiert, während Sie wirken, reisen, in Katzen- oder Bärengestalt sind oder keinen Gegner im Ziel haben.",
-- 30101468 English: Recommended for Feral from level 10, after simulator and Wowhead's Phase 5
--     list. Puts you in Cat Form, opens from Prowl with Savage Roar and Ravage, keeps Savage Roar
--     up, uses Predatory Swiftness for a Healing Touch at four or five combo points with Dream of
--     Cenarius, Rip at five points (Ferocious Bite refreshes it below 25% health), Ferocious Bite
--     at five points while Rip and Savage Roar both have six seconds left, Rake, Thrash on
--     Clearcasting, Shred on Clearcasting or Berserk when the target is not attacking you (Rotation
--     Master cannot tell whether you are behind it) and Mangle; Thrash and Swipe at four enemies.
--     In Bear Form it gives a short tanking list. Reminders: Tiger's Fury under 35 energy, Berserk
--     with it on elites or long fights, Incarnation, Force of Nature, Nature's Vigil, Skull Bash,
--     Survival Instincts and Barkskin when low, Mark of the Wild. Bear- and Wrath-weaving, and
--     Heart of the Wild, stay manual.
[54] = "Empfohlen für Wildheit ab Stufe 10, nach Simulation und der Liste von Wowhead für Phase 5. Versetzt Sie in Katzengestalt, eröffnet aus Schleichen mit Wildem Brüllen und Verheeren, hält Wildes Brüllen aufrecht, nutzt Schnelligkeit des Raubtiers für eine Heilende Berührung bei vier oder fünf Combopunkten mit Traum des Cenarius, Zerfetzen bei fünf Punkten (Wilder Biss erneuert es unter 25 % Gesundheit), Wilder Biss bei fünf Punkten, solange Zerfetzen und Wildes Brüllen beide noch sechs Sekunden haben, Krallenhieb, Hauen bei Freizaubern, Schreddern bei Freizaubern oder Berserker, wenn das Ziel Sie nicht angreift (Rotation Master kann nicht erkennen, ob Sie hinter ihm stehen), und Zerfleischen; Hauen und Prankenhieb ab vier Gegnern. In Bärengestalt gibt sie eine kurze Tankliste. Erinnerungen: Tigerfuror unter 35 Energie, Berserker damit gegen Elitegegner oder bei langen Kämpfen, Inkarnation, Naturgewalt, Wache der Natur, Schädelstoß, Überlebensinstinkte und Baumrinde bei niedriger Gesundheit, Mal der Wildnis. Bären- und Zorn-Weaving sowie Herz der Wildnis bleiben manuell.",
-- 450e41c9 English: Bite only in execute (Icy Veins)
[55] = "Wilder Biss nur in der Hinrichtungsphase (Icy Veins)",
-- 34b2bf98 English: Icy Veins' Feral order (Wowhead's Bite rule agrees), an alternative to the
--     recommended Feral premade: enable it and disable that one, or raise its priority. Same
--     opener, Savage Roar, Healing Touch and AoE, but combo points above 25% target health go only
--     to Rip and Savage Roar: Ferocious Bite only refreshes Rip in execute (or spends five points
--     before you learn Rip). Rake refreshes at two seconds, Thrash only on Clearcasting, and
--     Berserk waits for 90 energy with Tiger's Fury at least 15 seconds away.
[56] = "Die Wildheit-Reihenfolge von Icy Veins (die Biss-Regel von Wowhead stimmt überein), eine Alternative zur empfohlenen integrierten Wildheit-Rotation: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Dieselbe Eröffnung, dasselbe Wilde Brüllen, dieselbe Heilende Berührung und derselbe Flächenschaden, aber Combopunkte gehen über 25 % Gesundheit des Ziels nur in Zerfetzen und Wildes Brüllen: Wilder Biss erneuert Zerfetzen nur in der Hinrichtungsphase (oder gibt fünf Punkte aus, bevor Sie Zerfetzen erlernen). Krallenhieb wird bei zwei Sekunden erneuert, Hauen nur bei Freizaubern, und Berserker wartet auf 90 Energie, wenn Tigerfuror noch mindestens 15 Sekunden entfernt ist.",
-- fb9929bb English: Recommended for Guardian tanks from level 10, after simulator and Wowhead's
--     Phase 5 list. Puts you in Bear Form, pulls with Faerie Fire from range or Mangle, keeps
--     Weakened Blows up with Thrash and Weakened Armor with Faerie Fire on elites, uses a Dream of
--     Cenarius Healing Touch when hurt, Mangle on cooldown, Thrash and Swipe at three enemies, then
--     Lacerate, Thrash and Faerie Fire. In Cat Form (Heart of the Wild) it gives a short damage
--     list. Reminders: Savage Defense whenever it is down, Enrage for rage, Frenzied Regeneration
--     when low or rage-capped, Maul above 90 rage or on Tooth and Claw, Barkskin while the target
--     attacks you, Survival Instincts when low, Berserk and Incarnation on two enemies or a boss,
--     Force of Nature, Nature's Vigil, Cenarion Ward, Skull Bash, Mark of the Wild. Taunting and
--     Might of Ursoc stay manual (both reminders are off by default).
[57] = "Empfohlen für Wächter-Tanks ab Stufe 10, nach Simulation und der Liste von Wowhead für Phase 5. Versetzt Sie in Bärengestalt, zieht mit Feenfeuer aus der Distanz oder mit Zerfleischen, hält Kampfesmüdigkeit mit Hauen und Rüstungsschwächung mit Feenfeuer auf Elitegegnern aufrecht, nutzt eine Heilende Berührung durch Traum des Cenarius bei Verletzung, Zerfleischen bei Abklingzeit-Ende, Hauen und Prankenhieb ab drei Gegnern, dann Aufschlitzen, Hauen und Feenfeuer. In Katzengestalt (Herz der Wildnis) gibt sie eine kurze Schadensliste. Erinnerungen: Wilde Verteidigung, wann immer sie fehlt, Wutanfall für Wut, Rasende Regeneration bei niedriger Gesundheit oder maximaler Wut, Zermalmen über 90 Wut oder bei Mit Klauen und Zähnen, Baumrinde, während das Ziel Sie angreift, Überlebensinstinkte bei niedriger Gesundheit, Berserker und Inkarnation gegen zwei Gegner oder einen Boss, Naturgewalt, Wache der Natur, Cenarischer Zauberschutz, Schädelstoß, Mal der Wildnis. Spotten und Ursocs Macht bleiben manuell (beide Erinnerungen sind standardmäßig deaktiviert).",
-- de6705ed English: Recommended for Restoration from level 10, after Wowhead's Phase 5 group
--     healing. Heals your current friendly target, or you with no target; choosing whom to heal is
--     up to you. Swiftmend on a target with your HoT when it is low, when Harmony has dropped, or
--     into Wild Growth with Soul of the Forest; Wild Growth when three people nearby are hurt;
--     instant Healing Touch on Nature's Swiftness; Regrowth on Clearcasting or a dying target;
--     Rejuvenation; then Healing Touch and Nourish while standing still. An attackable target gets
--     Moonfire and Wrath. Reminders: Lifebloom stacks and Ironbark on your focus (set the tank as
--     focus), Wild Mushroom: Bloom on group damage, Force of Nature, Incarnation, Nature's Vigil,
--     Nature's Swiftness, Innervate, Nature's Cure, Cenarion Ward, Barkskin, Mark of the Wild. Wild
--     Mushroom placement, Tranquility and Genesis reminders are off by default.
[58] = "Empfohlen für Wiederherstellung ab Stufe 10, nach der Gruppenheilung von Wowhead für Phase 5. Heilt Ihr aktuelles freundliches Ziel oder Sie selbst ohne Ziel; wen Sie heilen, entscheiden Sie. Rasche Heilung auf ein Ziel mit Ihrem HoT, wenn es wenig Gesundheit hat, wenn Harmonie ausgelaufen ist oder als Vorbereitung auf Wildwuchs mit Seele des Waldes; Wildwuchs, wenn drei Personen in der Nähe verletzt sind; sofortige Heilende Berührung bei Schnelligkeit der Natur; Nachwachsen bei Freizaubern oder auf ein sterbendes Ziel; Verjüngung; dann Heilende Berührung und Pflege im Stillstand. Ein angreifbares Ziel erhält Mondfeuer und Zorn. Erinnerungen: Stapel von Blühendes Leben und Eisenborke auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Wildpilz: Erblühen bei Gruppenschaden, Naturgewalt, Inkarnation, Wache der Natur, Schnelligkeit der Natur, Anregen, Heilung der Natur, Cenarischer Zauberschutz, Baumrinde, Mal der Wildnis. Erinnerungen an das Platzieren von Wildpilz, Gelassenheit und Genesis sind standardmäßig deaktiviert.",
-- f3d02e30 English: Tank healing (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid,
--     Mists of Pandaria Classic (variant key: Restoration / Wowhead). Names in parentheses (guide
--     or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[59] = "Tankheilung (Wowhead)",
-- 28164e24 English: Wowhead's single-target tank-healing order, an alternative to the recommended
--     Restoration premade for when you are assigned to the tank: enable it and disable that one, or
--     raise its priority. Keep the tank targeted: it keeps three Lifeblooms and Rejuvenation on it,
--     uses Regrowth for heavy damage, Nourish for light damage, Healing Touch once Lifebloom and
--     Rejuvenation are rolling and the tank is below half, and Swiftmend to keep it topped up. Same
--     reminders as the recommended premade.
[60] = "Die Einzelziel-Tankheilung von Wowhead, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, wenn Sie dem Tank zugewiesen sind: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Behalten Sie den Tank im Ziel: Sie hält drei Blühendes Leben und Verjüngung auf ihm, nutzt Nachwachsen bei hohem Schaden, Pflege bei leichtem Schaden, Heilende Berührung, sobald Blühendes Leben und Verjüngung laufen und der Tank unter der Hälfte ist, und Rasche Heilung, um ihn aufgefüllt zu halten. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
}
